function fetchConfig(type = 'json') {
	return {
		method: 'POST',
		headers: {'Content-Type': 'application/json', 'Accept': `application/${type}`}
	};
}
if ((typeof window.Shopify) == 'undefined') {
	window.Shopify = {};
}
Shopify.postLink = function(path, options) {
	options = options || {};
	var method = options['method'] || 'post';
	var params = options['parameters'] || {};

	var form = document.createElement("form");
	form.setAttribute("method", method);
	form.setAttribute("action", path);

	for(var key in params) {
		var hiddenField = document.createElement("input");
		hiddenField.setAttribute("type", "hidden");
		hiddenField.setAttribute("name", key);
		hiddenField.setAttribute("value", params[key]);
		form.appendChild(hiddenField);
	}
	document.body.appendChild(form);
	form.submit();
	document.body.removeChild(form);
};
if (!customElements.get('countdown-timer')) {
	customElements.define('countdown-timer', class CountdownTimer extends HTMLElement {
		constructor() {
			super();
			this.dateStart = new Date(this.dataset.start).getTime();
			this.dateEnd = new Date(this.dataset.end).getTime();
			if(!isNaN(this.dateStart) && !isNaN(this.dateEnd) ){
				this.initTimer();
			}
		}
		initTimer(){
			let _this = this;
			let timerInterval = setInterval(function (){
				let currentDate = new Date().getTime();
				let distance = _this.dateEnd - currentDate;
				let distanceStart = _this.dateStart - currentDate;
				let days = Math.floor(distance / (1000 * 60 * 60 * 24));
				let hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
				let minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
				let seconds = Math.floor((distance % (1000 * 60)) / 1000);

				if(_this.querySelector('[data-days]')){
					_this.querySelector('[data-days]').innerHTML = ((days < 10) ? "0" : "") + days;
				}
				if(_this.querySelector('[data-hours]')){
					_this.querySelector('[data-hours]').innerHTML = ((hours < 10) ? "0" : "") + hours;
				}
				if(_this.querySelector('[data-minutes]')){
					_this.querySelector('[data-minutes]').innerHTML = ((minutes < 10) ? "0" : "") + minutes;
				}
				if(_this.querySelector('[data-seconds]')){
					_this.querySelector('[data-seconds]').innerHTML = ((seconds < 10) ? "0" : "") + seconds;
				}
				if (distance < 0 || distanceStart > 0) {
					clearInterval(timerInterval);
					_this.remove();
				}else{
					_this.removeAttribute('style')
				}

			},1000)
		}
	});
}
if (!customElements.get('product-card-variant')) {
	customElements.define('product-card-variant', class ProductCardVariant extends HTMLElement {
		constructor() {
			super();
			const _this = this;
			this.inputs = this.querySelectorAll('input[type="radio" ]');// submit event
			if(this.inputs){
				this.inputs.forEach(function (input){
					input.addEventListener('change', function (){
						let selectedValue = this.value;
						if(this.name.includes('-colors-option')){
							_this.updateOptions(selectedValue);
						}else{
							if(this.closest('.product-card').querySelector('product-form input[name="id"]')){
								this.closest('.product-card').querySelector('product-form input[name="id"]').value = selectedValue;
								this.closest('.product-card').querySelector('product-form form').dispatchEvent(new Event('submit'));;
								this.checked = false;
							}
						}

					})
				})
			}
		}

		updateOptions(productHandle){
			let _this = this;
			fetch(window.shopUrl+`?view=template-${Math.random()}&section_id=ajax-product-card-blocks&product=${productHandle}&end-product`).then(function (response) {
				return response.text();
			}).then(function (responseText) {
				const doc = new DOMParser().parseFromString(responseText, 'text/html');
				const fetchOption = doc.querySelector('#product-options');
				const fetchImage = doc.querySelector('#product-images');
				if(_this.closest('.product-card')){
					let option = _this.closest('.product-card').querySelector('.product-card-option-list-wrapper');
					let image = _this.closest('.product-card').querySelector('.product-card-image-wrapper');
					if(option && fetchOption){
						option.innerHTML = fetchOption.innerHTML
					}
					if(image && fetchImage){
						image.innerHTML = fetchImage.innerHTML
					}
				}
			}).catch(function (err) {
				console.error('Something went wrong.', err);
			});
		}

	});
}

function updateCartCount() {
	fetch('/cart.js').then((response) => {
		return response.text();
	}).then((state) => {
		const cart = JSON.parse(state);
		const cartCount = document.querySelectorAll('[data-cart-count]');
		if(cartCount){
			cartCount.forEach(function (element){
				element.innerHTML = '-' + cart.item_count;
			})
		}
	}) .catch((e) => {
		console.error(e);
	});
}
function updateCartPopup(){
	document.querySelector('#cart-popup').classList.add('loading')
	fetch(window.routes.cart_url + '?section_id=ajax-cart-popup')
		.then((response) => response.text())
		.then((responseText) => {
			const html = new DOMParser().parseFromString(responseText, 'text/html');
			const fetchCartPopup = html.querySelector('#cart-popup');
			const cartPopup = document.querySelector('#cart-popup');
			if(cartPopup && fetchCartPopup){
				cartPopup.innerHTML = fetchCartPopup.innerHTML;
			}
			updateCartPopupEvent()
			document.querySelector('#cart-popup').classList.remove('loading')
		})
		.catch(e => {
			console.error(e);
		});
}
function updateCartPopupEvent(){
	let quantityButtons = document.querySelectorAll('#cart-popup .js-quantity-button');
	if (quantityButtons) {
		quantityButtons.forEach(function (button) {
			button.addEventListener('click', function () {
				let oldValue = '';
				let newValue = 0;
				let quantityInput = '';
				let quantityBlock = this.closest('.js-quantity');
				if (quantityBlock) {
					quantityInput = quantityBlock.querySelector('.js-quantity-input');
					if (quantityInput) {
						oldValue = parseInt(quantityInput.value);
						if (this.classList.contains('quantity-button-increase')) {
							newValue = oldValue + 1;
						} else {
							if (oldValue > 0) {
								newValue = oldValue - 1;
							} else {
								newValue = 0;
							}
						}
						quantityInput.value = newValue;
						quantityInput.dispatchEvent(new Event('change'));
					}
				}
			});
		});
	}

	let cartRecommendationSlider = document.querySelector('.js-cart-popup-recommendation-list');
	let cartRecommendationSliderScrolbar = document.querySelector('.cart-popup-recommendation .swiper-scrollbar');
	if (cartRecommendationSlider) {
		const newCartRecommendationSwiper = new Swiper(cartRecommendationSlider, {
			slidesPerView: 3.65,
			paginationClickable: true,
			spaceBetween: 4,
			autoHeight: true,
			scrollbar: {
				el: cartRecommendationSliderScrolbar,
				draggable: true
			},
			breakpoints: {
				768: {
					slidesPerView: 4
				}
			}
		});
	}
	let cartPopupButton = document.querySelectorAll("#cart-popup .js-cart-trigger");
	if (cartPopupButton) {
		cartPopupButton.forEach(function (button) {
			button.addEventListener('click', function () {
				if (this.dataset.type == 'open') {
					if (document.querySelector('#cart-popup')) {
						document.querySelector('#cart-popup').classList.add('open');
						document.body.classList.add('disable-scroll');
					}
					if (document.querySelector('.cart-popup-overflow')) {
						document.querySelector('.cart-popup-overflow').classList.add('open');
					}
				} else {
					if (document.querySelector('#cart-popup')) {
						document.querySelector('#cart-popup').classList.remove('open');
						document.body.classList.remove('disable-scroll');
					}
					if (document.querySelector('.cart-popup-overflow')) {
						document.querySelector('.cart-popup-overflow').classList.remove('open');
					}
				}
			});
		});
	}
}
let cartOpenTrigger = document.querySelector('.js-cart-trigger-open');
if(cartOpenTrigger){
	cartOpenTrigger.addEventListener('click', function (){
		if(this.dataset.loaded != 'true'){
			this.dataset.loaded = 'true';
			updateCartPopup();
		}
		if (document.querySelector('#cart-popup')) {
			document.querySelector('#cart-popup').classList.add('open');
			document.body.classList.add('disable-scroll');
		}
		if (document.querySelector('.cart-popup-overflow')) {
			document.querySelector('.cart-popup-overflow').classList.add('open');
		}
	})
}
