function addFreeShipping(){
	let freeShipping = document.querySelector('.js-free-shipping-info');
	if(freeShipping){
		fetch(
			'/browsing_context_suggestions.json'
			+ '?country[enabled]=true'
			+ `&country[exclude]=${window.Shopify.country}`
			+ '&language[enabled]=true'
			+ `&language[exclude]=${window.Shopify.language}`
		).then(r => r.json()).then(function (data) {
			if (data.detected_values.country.handle) {
				if(freeShipping.querySelector('.icon')){
					freeShipping.querySelector('.icon').innerHTML = `
				<img src="https://flagsapi.com/${data.detected_values.country.handle}/flat/64.png" alt="icon">
			`
				}
				console.log(data.detected_values.country.handle)
				if(window.freeShippingCountries && window.freeShippingCountries.includes(data.detected_values.country.handle)){
					freeShipping.removeAttribute('style');
				}else{
					freeShipping.remove();
				}

			}
		});
	}

}
