function reloadProductCardHover(){
	let productCardOptionTrigger = document.querySelectorAll('.js-product-card-options-button');
	if (productCardOptionTrigger) {
		productCardOptionTrigger.forEach(function (element) {
			if(!element.classList.contains('hovered')){
				element.classList.add('hovered')
				element.addEventListener('mouseenter', function () {
					if (this.closest('.product-card').querySelector('.product-card-options')) {
						this.closest('.product-card').querySelector('.product-card-options').classList.add('show');
					}
					if (this.closest('.product-card').querySelector('.js-product-card-options-close')) {
						this.closest('.product-card').querySelector('.js-product-card-options-close').classList.add('show');
					}
				});
				element.addEventListener('click', function () {
					if (this.closest('.product-card').querySelector('.product-card-options')) {
						this.closest('.product-card').querySelector('.product-card-options').classList.add('show');
					}
					if (this.closest('.product-card').querySelector('.js-product-card-options-close')) {
						this.closest('.product-card').querySelector('.js-product-card-options-close').classList.add('show');
					}
				});
			}
		});
	}
	let productCardOptionClose = document.querySelectorAll('.js-product-card-options-close');
	if (productCardOptionClose) {
		productCardOptionClose.forEach(function (element) {
			element.addEventListener('click', function () {
				if (this.closest('.product-card').querySelector('.product-card-options')) {
					this.closest('.product-card').querySelector('.product-card-options').classList.remove('show');
				}
				this.classList.remove('show');
			});
		});
	}
	let productCardOptionTriggerClose = document.querySelectorAll('.js-product-card-options-button-close');
	if (productCardOptionTriggerClose) {
		productCardOptionTriggerClose.forEach(function (element) {
			element.addEventListener('click', function () {
				this.classList.remove('show');
				this.closest('.product-card').querySelector('.product-card-options').classList.remove('show');
			});
		});
	}
	let productCardImage = document.querySelectorAll('.product-card .product-card-image');
	if (productCardImage) {
		productCardImage.forEach(function (element) {
			element.addEventListener('mouseleave', function () {
				if (this.closest('.product-card').querySelector('.product-card-options')) {
					this.closest('.product-card').querySelector('.product-card-options').classList.remove('show');
				}
				if (this.closest('.product-card').querySelector('.js-product-card-options-close')) {
					this.closest('.product-card').querySelector('.js-product-card-options-close').classList.remove('show');
				}
			});
		});
	}
}
let sizeSwitcher = document.querySelectorAll('.js-size-switcher');
if(sizeSwitcher){
	sizeSwitcher.forEach(function (checkbox){
		checkbox.addEventListener('change',function (){
			let cmTable = this.closest('.sizes-popup').querySelector('.sizes-popup-table-cm'),
			incTable = this.closest('.sizes-popup').querySelector('.sizes-popup-table-in'),
			label = this.closest('.sizes-popup').querySelector('label.switcher');
			if(this.checked){
				if(cmTable){
					cmTable.style.display = 'none';
				}
				if(incTable){
					incTable.removeAttribute('style')
				}
				if(label){
					label.classList.add('active')
				}
			}else{
				if(incTable){
					incTable.style.display = 'none';
				}
				if(cmTable){
					cmTable.removeAttribute('style')
				}
				if(label){
					label.classList.remove('active')
				}
			}
		})
	})
}

function setResponsiveVideo(){
	let responsiveVideo = document.querySelectorAll("source[data-responsive-video]");
	if(responsiveVideo){

		responsiveVideo.forEach(source=>{
			if(source.hasAttribute('data-mobile-src') && source.hasAttribute('data-desktop-src')){
				if(window.matchMedia('(max-width: 767px)').matches){
					if(source.src.replace('https:', '') != source.dataset.mobileSrc){
						source.src = source.dataset.mobileSrc;
						source.closest('video').load();
					}
				}else{
					if(source.src.replace('https:', '') != source.dataset.desktopSrc){
						source.src = source.dataset.desktopSrc;
						source.closest('video').load();
					}
				}
			}
		})
	}
}
setResponsiveVideo()
window.addEventListener('resize',function (){
	setResponsiveVideo()
})
